class Solution:
    def longestEcho(self, s: str) -> int:
        n = len(s)
        best_len, best_i = 1, 0
        for i in range(n):
            for j in range(i + best_len, n):
                a, b = i, j
                while a < b and s[a] == s[b]:
                    a, b = a + 1, b - 1
                if a >= b:
                    best_len, best_i = j - i + 1, i
        return best_len

