class Solution {
    public int longestEcho(String s) {
        int n = s.length(), bestLen = 1, bestI = 0;
        for (int i = 0; i < n; i++)
            for (int j = i + bestLen; j < n; j++) {
                int a = i, b = j;
                while (a < b && s.charAt(a) == s.charAt(b)) { a++; b--; }
                if (a >= b) { bestLen = j - i + 1; bestI = i; }
            }
        return bestLen;
    }
}

