class Solution:
    def longestEcho(self, s: str) -> int:
        n = len(s)
        best_len, best_i = 1, 0
        for c in range(2 * n - 1):
            i, j = c // 2, c // 2 + c % 2
            while i >= 0 and j < n and s[i] == s[j]:
                i, j = i - 1, j + 1
            if j - i - 1 > best_len:
                best_len, best_i = j - i - 1, i + 1
        return best_len

